"""Deterministic generation of distinct record ids."""

import random

import pytest


def make_ids(n: int, seed: int) -> list[int]:
    """Return n distinct record ids, identical on every run for the same seed.

    The ids are produced from a private, seeded generator; global random
    state is neither read nor modified, and no I/O or OS entropy is used.

    Raises:
        ValueError: if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    rng = random.Random(seed)
    return rng.sample(range(1, 2**63), n)


def test_make_ids_length() -> None:
    assert len(make_ids(5, seed=1)) == 5


def test_make_ids_zero() -> None:
    assert make_ids(0, seed=1) == []


def test_make_ids_distinct() -> None:
    ids = make_ids(100, seed=42)
    assert len(set(ids)) == len(ids)


def test_make_ids_deterministic() -> None:
    assert make_ids(20, seed=7) == make_ids(20, seed=7)


def test_make_ids_seed_changes_output() -> None:
    assert make_ids(10, seed=1) != make_ids(10, seed=2)


def test_make_ids_negative_raises() -> None:
    with pytest.raises(ValueError):
        make_ids(-1, seed=0)
